fizzbuzz.code:
for i in {1..15}; do
    case $(( i % 15 )) in
        0)        echo FizzBuzz ;;
        3|6|9|12) echo Fizz ;;
        5|10)     echo Buzz ;;
        *)        echo "$i" ;;
    esac
done

higher-order.code:
# A function's name is just a word, so it can be passed as an argument
# and called as "$1". Lists are streams of lines flowing through a pipeline.
filter() { local x; while read -r x; do "$1" "$x" && echo "$x"; done; }
map()    { local x; while read -r x; do "$1" "$x"; done; }

is_even() { (( $1 % 2 == 0 )); }
square()  { echo $(( $1 * $1 )); }

# The unquoted $( ) is split into words, which echo joins with spaces.
echo $(printf '%s\n' {1..10} | filter is_even | map square)
